@import url('https://fonts.googleapis.com/css2?family=Playfair+Display:ital,wght@0,400;0,700;0,900;1,400;1,700&family=Inter:wght@300;400;500;600&display=swap');

*, *::before, *::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

:root {
  --bg: #F5F2ED;
  --text: #1A1A1A;
  --text-light: #6B6560;
  --accent-terracotta: #C4755B;
  --accent-sage: #8B9E7E;
  --accent-sand: #D4B896;
  --serif: 'Playfair Display', Georgia, 'Times New Roman', serif;
  --sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
}

html {
  font-size: 16px;
  scroll-behavior: smooth;
}

body {
  background-color: var(--bg);
  color: var(--text);
  font-family: var(--sans);
  font-weight: 400;
  line-height: 1.7;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  overflow-x: hidden;
}

a {
  color: var(--text);
  text-decoration: none;
  transition: opacity 0.25s ease;
}

a:hover {
  opacity: 0.6;
}

/* =========================================
   HEADER / NAVIGATION
   ========================================= */

header {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  z-index: 100;
  padding: 1.75rem 3rem;
  display: flex;
  justify-content: space-between;
  align-items: center;
  background: var(--bg);
  transition: background 0.3s ease;
}

.logo {
  font-family: var(--serif);
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: -0.02em;
}

nav.desktop-nav {
  display: flex;
  gap: 2.5rem;
}

nav.desktop-nav a {
  font-size: 0.875rem;
  font-weight: 400;
  letter-spacing: 0.03em;
  text-transform: lowercase;
}

.hamburger {
  display: none;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  width: 32px;
  height: 32px;
  cursor: pointer;
  background: none;
  border: none;
  position: relative;
  z-index: 200;
}

.hamburger span {
  display: block;
  width: 24px;
  height: 1.5px;
  background: var(--text);
  transition: all 0.35s ease;
}

.hamburger span:nth-child(1) {
  margin-bottom: 6px;
}

.hamburger span:nth-child(2) {
  margin-bottom: 0;
}

.hamburger.active span:nth-child(1) {
  transform: rotate(45deg) translate(2.5px, 2.5px);
}

.hamburger.active span:nth-child(2) {
  transform: rotate(-45deg) translate(2.5px, -2.5px);
}

/* Mobile overlay menu */
.mobile-menu {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: var(--bg);
  z-index: 150;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  gap: 2rem;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.4s ease;
}

.mobile-menu.active {
  opacity: 1;
  pointer-events: auto;
}

.mobile-menu a {
  font-family: var(--serif);
  font-size: 2.5rem;
  font-weight: 700;
  letter-spacing: -0.02em;
}

/* =========================================
   HERO SECTION
   ========================================= */

.hero {
  padding: 10rem 3rem 4rem;
  max-width: 900px;
}

.hero h1 {
  font-family: var(--serif);
  font-size: clamp(2.5rem, 5.5vw, 4.5rem);
  font-weight: 700;
  line-height: 1.15;
  letter-spacing: -0.03em;
}

/* =========================================
   MEDIA SHOWCASE
   ========================================= */

.media-showcase {
  display: grid;
  grid-template-columns: 1fr 1.2fr 0.8fr;
  gap: 1.25rem;
  padding: 3rem 3rem 5rem;
}

.media-block {
  aspect-ratio: 4 / 5;
  border-radius: 4px;
}

.media-block:nth-child(1) {
  background-color: var(--accent-terracotta);
}

.media-block:nth-child(2) {
  background-color: var(--accent-sage);
  aspect-ratio: 16 / 10;
}

.media-block:nth-child(3) {
  background-color: var(--accent-sand);
}

/* =========================================
   CLIENT MARQUEE
   ========================================= */

.marquee-section {
  padding: 4rem 0;
  overflow: hidden;
}

.marquee-row {
  display: flex;
  white-space: nowrap;
  margin-bottom: 1rem;
}

.marquee-track {
  display: flex;
  animation: marquee-left 30s linear infinite;
}

.marquee-row:nth-child(2) .marquee-track {
  animation: marquee-right 30s linear infinite;
}

.marquee-track span {
  font-family: var(--serif);
  font-size: clamp(1.5rem, 3vw, 2.5rem);
  font-weight: 700;
  letter-spacing: -0.01em;
  padding: 0 1.5rem;
  color: var(--text);
  opacity: 0.85;
}

.marquee-track .separator {
  opacity: 0.3;
  font-size: clamp(1rem, 2vw, 1.5rem);
  display: inline-flex;
  align-items: center;
  padding: 0 0.5rem;
}

@keyframes marquee-left {
  0% { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}

@keyframes marquee-right {
  0% { transform: translateX(-50%); }
  100% { transform: translateX(0); }
}

/* =========================================
   ABOUT SECTION
   ========================================= */

.about-section {
  padding: 6rem 3rem 8rem;
  max-width: 1200px;
  margin: 0 auto;
}

.about-section .label {
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--text-light);
  margin-bottom: 2.5rem;
}

.about-section p {
  font-family: var(--serif);
  font-size: clamp(1.25rem, 2.2vw, 1.75rem);
  line-height: 1.6;
  margin-bottom: 1.75rem;
  max-width: 850px;
}

/* =========================================
   FOUNDER LETTER (neweno)
   ========================================= */

.founder-letter {
  padding: 10rem 3rem 8rem;
  max-width: 700px;
  margin: 0 auto;
}

.founder-letter .letter-heading {
  font-family: var(--serif);
  font-size: clamp(2.5rem, 5vw, 4rem);
  font-weight: 700;
  line-height: 1.15;
  letter-spacing: -0.03em;
  margin-bottom: 4rem;
}

.founder-letter p {
  font-size: 1.125rem;
  line-height: 1.85;
  margin-bottom: 1.75rem;
  color: var(--text);
}

.founder-letter p:first-of-type::first-letter {
  font-family: var(--serif);
  font-size: 3.75rem;
  float: left;
  line-height: 0.8;
  margin-right: 0.5rem;
  margin-top: 0.15rem;
  font-weight: 700;
  color: var(--accent-terracotta);
}

.founder-letter .letter-sign-off {
  margin-top: 3.5rem;
  font-family: var(--serif);
  font-size: 1.25rem;
  font-style: italic;
  color: var(--text-light);
}

/* =========================================
   SERVICES PAGE
   ========================================= */

.philosophy-section {
  padding: 10rem 3rem 5rem;
  max-width: 900px;
  margin: 0 auto;
}

.philosophy-section h1 {
  font-family: var(--serif);
  font-size: clamp(2.5rem, 5vw, 4rem);
  font-weight: 700;
  line-height: 1.15;
  letter-spacing: -0.03em;
  margin-bottom: 3rem;
}

.philosophy-section p {
  font-size: 1.125rem;
  line-height: 1.85;
  margin-bottom: 1.75rem;
  max-width: 700px;
}

.divider {
  width: 60px;
  height: 1.5px;
  background: var(--text);
  opacity: 0.2;
  margin: 4rem auto;
}

.services-section {
  padding: 2rem 3rem 8rem;
  max-width: 900px;
  margin: 0 auto;
}

.services-section .question-heading {
  font-family: var(--serif);
  font-size: clamp(1.75rem, 3vw, 2.5rem);
  font-weight: 700;
  font-style: italic;
  line-height: 1.3;
  margin-bottom: 3.5rem;
  letter-spacing: -0.02em;
}

.service-item {
  margin-bottom: 3rem;
}

.service-item h3 {
  font-family: var(--serif);
  font-size: 1.5rem;
  font-weight: 700;
  margin-bottom: 1rem;
}

.service-item p {
  font-size: 1.05rem;
  line-height: 1.8;
  color: var(--text);
  max-width: 700px;
}

/* =========================================
   CLIENTS PAGE
   ========================================= */

.clients-heading {
  padding: 10rem 3rem 3rem;
  max-width: 1200px;
  margin: 0 auto;
}

.clients-heading h1 {
  font-family: var(--serif);
  font-size: clamp(2.5rem, 5vw, 4rem);
  font-weight: 700;
  letter-spacing: -0.03em;
}

.clients-heading .subtitle {
  font-size: 1rem;
  color: var(--text-light);
  margin-top: 0.5rem;
}

.clients-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 2.5rem 3rem;
  padding: 3rem 3rem 8rem;
  max-width: 1200px;
  margin: 0 auto;
}

.client-card h3 {
  font-family: var(--serif);
  font-size: 1.35rem;
  font-weight: 700;
  margin-bottom: 0.6rem;
  letter-spacing: -0.01em;
}

.client-card p {
  font-size: 0.925rem;
  line-height: 1.65;
  color: var(--text-light);
}

/* =========================================
   CONTACT PAGE
   ========================================= */

.contact-hero {
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  padding: 3rem;
  text-align: center;
}

.contact-hero h1 {
  font-family: var(--serif);
  font-size: clamp(5rem, 15vw, 14rem);
  font-weight: 900;
  letter-spacing: -0.04em;
  line-height: 0.95;
  margin-bottom: 3rem;
}

.contact-links {
  display: flex;
  gap: 2.5rem;
  justify-content: center;
  flex-wrap: wrap;
}

.contact-links a {
  font-size: 1.1rem;
  font-weight: 400;
  letter-spacing: 0.02em;
  border-bottom: 1px solid transparent;
  padding-bottom: 2px;
  transition: border-color 0.3s ease, opacity 0.25s ease;
}

.contact-links a:hover {
  border-bottom-color: var(--text);
  opacity: 1;
}

/* =========================================
   FOOTER
   ========================================= */

footer {
  padding: 3rem;
  text-align: center;
  font-size: 0.8rem;
  color: var(--text-light);
  letter-spacing: 0.03em;
}

/* =========================================
   RESPONSIVE
   ========================================= */

@media (max-width: 768px) {
  header {
    padding: 1.25rem 1.5rem;
  }

  nav.desktop-nav {
    display: none;
  }

  .hamburger {
    display: flex;
  }

  .hero {
    padding: 8rem 1.5rem 3rem;
  }

  .media-showcase {
    grid-template-columns: 1fr;
    padding: 2rem 1.5rem 3rem;
  }

  .media-block {
    aspect-ratio: 16 / 10;
  }

  .about-section {
    padding: 4rem 1.5rem 5rem;
  }

  .founder-letter {
    padding: 8rem 1.5rem 5rem;
  }

  .philosophy-section {
    padding: 8rem 1.5rem 3rem;
  }

  .services-section {
    padding: 2rem 1.5rem 5rem;
  }

  .clients-heading {
    padding: 8rem 1.5rem 2rem;
  }

  .clients-grid {
    grid-template-columns: 1fr;
    gap: 2rem;
    padding: 2rem 1.5rem 5rem;
  }

  .contact-hero h1 {
    font-size: clamp(3.5rem, 18vw, 8rem);
  }

  .contact-links {
    flex-direction: column;
    align-items: center;
    gap: 1.5rem;
  }

  footer {
    padding: 2rem 1.5rem;
  }
}

