@import url('https://fonts.googleapis.com/css2?family=Playfair+Display:ital,wght@0,400;0,700;0,900;1,400;1,700&family=Inter:wght@300;400;500;600&display=swap');

*, *::before, *::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

:root {
  --bg: #F5F2ED;
  --text: #1A1A1A;
  --text-light: #6B6560;
  --accent-terracotta: #C4755B;
  --accent-sage: #8B9E7E;
  --accent-sand: #D4B896;
  --serif: 'Playfair Display', Georgia, 'Times New Roman', serif;
  --sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
}

html {
  font-size: 16px;
  scroll-behavior: smooth;
}

body {
  background-color: var(--bg);
  color: var(--text);
  font-family: var(--sans);
  font-weight: 400;
  line-height: 1.7;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  overflow-x: hidden;
}

a {
  color: var(--text);
  text-decoration: none;
  transition: opacity 0.25s ease;
}

a:hover {
  opacity: 0.6;
}

/* =========================================
   HEADER / NAVIGATION
   ========================================= */

header {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  z-index: 100;
  padding: 1.75rem 3rem;
  display: flex;
  justify-content: space-between;
  align-items: center;
  background: var(--bg);
  transition: background 0.3s ease;
}

.logo {
  font-family: var(--serif);
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: -0.02em;
}

nav.desktop-nav {
  display: flex;
  gap: 2.5rem;
}

nav.desktop-nav a {
  font-size: 0.875rem;
  font-weight: 400;
  letter-spacing: 0.03em;
  text-transform: lowercase;
}

.hamburger {
  display: none;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  width: 32px;
  height: 32px;
  cursor: pointer;
  background: none;
  border: none;
  position: relative;
  z-index: 200;
}

.hamburger span {
  display: block;
  width: 24px;
  height: 1.5px;
  background: var(--text);
  transition: all 0.35s ease;
}

.hamburger span:nth-child(1) {
  margin-bottom: 6px;
}

.hamburger span:nth-child(2) {
  margin-bottom: 0;
}

.hamburger.active span:nth-child(1) {
  transform: rotate(45deg) translate(2.5px, 2.5px);
}

.hamburger.active span:nth-child(2) {
  transform: rotate(-45deg) translate(2.5px, -2.5px);
}

/* Mobile overlay menu */
.mobile-menu {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: var(--bg);
  z-index: 150;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  gap: 2rem;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.4s ease;
}

.mobile-menu.active {
  opacity: 1;
  pointer-events: auto;
}

.mobile-menu a {
  font-family: var(--serif);
  font-size: 2.5rem;
  font-weight: 700;
  letter-spacing: -0.02em;
}

/* =========================================
   HERO SECTION
   ========================================= */

.hero {
  padding: 10rem 3rem 4rem;
  max-width: 900px;
}

.hero h1 {
  font-family: var(--serif);
  font-size: clamp(2.5rem, 5.5vw, 4.5rem);
  font-weight: 700;
  line-height: 1.15;
  letter-spacing: -0.03em;
}

/* =========================================
   MEDIA SHOWCASE
   ========================================= */

.media-showcase {
  display: grid;
  grid-template-columns: 1fr 1.2fr 0.8fr;
  gap: 1.25rem;
  padding: 3rem 3rem 5rem;
}

.media-block {
  aspect-ratio: 4 / 5;
  border-radius: 4px;
}

.media-block:nth-child(1) {
  background-color: var(--accent-terracotta);
}

.media-block:nth-child(2) {
  background-color: var(--accent-sage);
  aspect-ratio: 16 / 10;
}

.media-block:nth-child(3) {
  background-color: var(--accent-sand);
}

